#!/bin/bash

if [ $# -lt 1 ];then
echo "$0 (src filename)  (dst path)"
exit 0
fi


file_h=${1##*/}
file_c=$(echo $file_h | awk -F '.' '{print $1}').c

if [ $# -eq 1 ];then
file=./$file_c
else
file=$2/$file_c
fi
echo "file = $file"

function create_head()
{
cat << EOF > $2
/**
 * @file $file_c
 * @brief this file was auto-generated by tuyaos v&v tools, developer can add implements between BEGIN and END
 *
 * @warning: changes between user 'BEGIN' and 'END' will be keeped when run tuyaos v&v tools
 *           changes in other place will be overwrited and lost
 *
 * @copyright Copyright 2020-2021 Tuya Inc. All Rights Reserved.
 *
 */

// --- BEGIN: user defines and implements ---
#include "$file_h"
#include "tuya_error_code.h"
#include "tkl_adapter.h"

// --- END: user defines and implements ---

EOF

}

function create_c_file() 
{
  create_head $1 $2

while read line
do
    #echo " == $line =="
    head=$(echo $line | awk '{print $1}');


    if [[ "$line" =~ "/*" ]] && [[ "$line" =~ "*/" ]];then 
	continue;
    fi

    if [[ "$line" =  "/**" ]] || [[ "$line" =  "/*" ]];then
        echo "$line" > tmp.txt
        save_flag=1
#	echo "/*"
	continue;
    fi

    if [ "$line" =  "*/" ];then
       echo " $line" >> tmp.txt
       echo >> tmp.txt
       save_flag=0
#      echo "*/"
       continue
    fi

    if [ "$save_flag" = "1" ];then
       if [ "$line" != "" ];then 
           echo " $line" >> tmp.txt
	   continue
       fi
    fi
     if [[ "$line" =~ "typedef struct" ]] && [[ "$line" =~ ";" ]]; then
	     struct_flag=1;
     fi

     if [ "$struct_flag" = "1" ];then
         if [[ "$line" =~ "}" ]];then
	     struct_flag=0;
         fi
         continue
     fi
    
    #if [ "$head" = "OPERATE_RET" ] || [ "$head" = "UINT32_T" ]  || [ "$head" = "INT32_T" ] || [ "$head" = "UINT8_T" ] || [ "$head" = "BOOL_T" ] || [ "$head" = "INT8_T" ] || [ "$head" =  "TUYA_CELLULAR_KEY_LISTENER" ] || [ "$head" = "TUYA_CELLULAR_MDS_STATUS_E" ]                     \
#     && [[ "$line" =~ "(" ]] && [[ "$line" =~ ")" ]] ;then

    if [ "$head" != "typedef" ] && [ "$head" != "#define" ] && [ "$head" != "#if" ] && [ "$head" != "}" ] && [[ "$line" =~ "(" ]] && [[ "$line" =~ ")" ]] ;then
	echo "$head,$line"
	line=${line//extern/}
        FUNCTION=${line//;/}
        RETURN=$(echo $line | awk '{print $1}'); 
    	CALL=$(echo $line | awk '{$1="";print}');

	reserve=${CALL//;/ }
	reserve=${reserve//(/ }
	reserve=${reserve//,/ }
	reserve=${reserve//)/ }

	NAME=$(echo $reserve | awk '{print $1}')
	TYPE=${line/$NAME/(*TYPE_T)}
	CALL=${CALL//$NAME/fun}

#	echo "RETURN:$RETURN"
#	echo "NAME:$NAME"
#	echo "CALL:$CALL"
#	echo "TYPE:$TYPE"
#	echo "FUNCTION:$FUNCTION"

        cat tmp.txt >> $2
	rm -rf tmp.txt

        echo $FUNCTION >> $2
   	echo "{" >> $2
        echo "    // --- BEGIN: user implements ---" >> $2
   	echo "    typedef $TYPE" >> $2
   	echo >> $2
   	if [ "$RETURN" = "OPERATE_RET" ];then
   		echo "    $RETURN ret = OPRT_NOT_SUPPORTED;" >> $2
	elif [ "$RETURN" = "TUYA_CELLULAR_KEY_LISTENER" ] || [ "$RETURN" = "VOID*" ] || [ "$RETURN" = "char*" ] || [ "$RETURN" = "void*" ];then
          	echo "    $RETURN ret = NULL;" >> $2
        elif [ "$RETURN" = "VOID_T" ] || [ "$RETURN" = "void" ];then
		:
	else
          	echo "    $RETURN ret = 0;" >> $2
   	fi
   	echo "    TYPE_T fun;" >> $2
   	echo   >> $2
   	echo "    fun = (TYPE_T)tkl_adapt_func_get(FUNC_NAME($NAME));" >> $2
   	echo   >> $2
   	echo "    if(fun) {" >> $2
        if [ "$RETURN" = "VOID_T" ] || [ "$RETURN" = "void" ];then
   	echo "        $CALL" >> $2
        else 
   	echo "        ret =$CALL" >> $2
	fi
   	echo "    }" >> $2
   	echo   >> $2
        if [ "$RETURN" = "VOID_T" ] || [ "$RETURN" = "void" ];then
   	echo "    return;" >> $2
	else
   	echo "    return ret;" >> $2
        fi
   	echo "    // --- END: user implements ---" >> $2
   	echo "}" >> $2
   	echo >> $2
    fi
done < $1 

    rm -rf tmp.txt
}

create_c_file $1 $file
